<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Conway's Game of Life</title>
    <style>
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            background-color: #1a1a1a;
            color: #e0e0e0;
            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
            display: flex;
            justify-content: center;
            align-items: center;
            min-height: 100vh;
            padding: 20px;
        }

        .container {
            text-align: center;
        }

        h1 {
            margin-bottom: 20px;
            font-size: 2.5em;
            background: linear-gradient(135deg, #00ff88, #00ccff);
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
            background-clip: text;
            font-weight: bold;
        }

        #life {
            display: block;
            border: 3px solid #00ff88;
            background-color: #0d0d0d;
            box-shadow: 0 0 30px rgba(0, 255, 136, 0.3);
            margin: 0 auto 30px;
            cursor: crosshair;
            width: 400px;
            height: 400px;
            image-rendering: pixelated;
        }

        .controls {
            display: flex;
            gap: 15px;
            justify-content: center;
            flex-wrap: wrap;
            margin-bottom: 20px;
        }

        button {
            padding: 12px 24px;
            font-size: 1em;
            font-weight: bold;
            border: 2px solid #00ff88;
            background-color: transparent;
            color: #00ff88;
            cursor: pointer;
            transition: all 0.2s ease;
            border-radius: 5px;
            text-transform: uppercase;
            letter-spacing: 1px;
        }

        button:hover {
            background-color: #00ff88;
            color: #1a1a1a;
            box-shadow: 0 0 20px rgba(0, 255, 136, 0.5);
            transform: scale(1.05);
        }

        button:active {
            transform: scale(0.95);
        }

        .info {
            color: #888;
            font-size: 0.9em;
            margin-top: 20px;
        }

        .gen-counter {
            font-size: 1.1em;
            margin-top: 15px;
            color: #00ccff;
        }
    </style>
</head>
<body>
    <div class="container">
        <h1>🧬 Conway's Game of Life 🧬</h1>
        <canvas id="life"></canvas>
        <div class="controls">
            <button id="step">Step</button>
            <button id="play">Play</button>
            <button id="random">Random</button>
            <button id="clear">Clear</button>
        </div>
        <div class="gen-counter">Generation: <span id="generation">0</span></div>
        <div class="info">Click and drag to draw • Double-click to clear</div>
    </div>

    <script>
        const canvas = document.getElementById('life');
        const ctx = canvas.getContext('2d');

        const GRID_WIDTH = 50;
        const GRID_HEIGHT = 50;
        const CELL_SIZE = 8;

        canvas.width = GRID_WIDTH * CELL_SIZE;
        canvas.height = GRID_HEIGHT * CELL_SIZE;

        let grid = Array(GRID_HEIGHT).fill(null).map(() => Array(GRID_WIDTH).fill(0));
        let running = false;
        let generation = 0;
        let animationId = null;

        function countNeighbors(x, y) {
            let count = 0;
            for (let dy = -1; dy <= 1; dy++) {
                for (let dx = -1; dx <= 1; dx++) {
                    if (dx === 0 && dy === 0) continue;
                    const nx = x + dx;
                    const ny = y + dy;
                    if (nx >= 0 && nx < GRID_WIDTH && ny >= 0 && ny < GRID_HEIGHT) {
                        count += grid[ny][nx];
                    }
                }
            }
            return count;
        }

        function computeNextGeneration() {
            const newGrid = Array(GRID_HEIGHT).fill(null).map(() => Array(GRID_WIDTH).fill(0));

            for (let y = 0; y < GRID_HEIGHT; y++) {
                for (let x = 0; x < GRID_WIDTH; x++) {
                    const alive = grid[y][x];
                    const neighbors = countNeighbors(x, y);

                    if (alive) {
                        if (neighbors === 2 || neighbors === 3) {
                            newGrid[y][x] = 1;
                        }
                    } else {
                        if (neighbors === 3) {
                            newGrid[y][x] = 1;
                        }
                    }
                }
            }

            return newGrid;
        }

        function draw() {
            ctx.fillStyle = '#0d0d0d';
            ctx.fillRect(0, 0, canvas.width, canvas.height);

            ctx.fillStyle = '#00ff88';
            for (let y = 0; y < GRID_HEIGHT; y++) {
                for (let x = 0; x < GRID_WIDTH; x++) {
                    if (grid[y][x]) {
                        ctx.fillRect(x * CELL_SIZE, y * CELL_SIZE, CELL_SIZE, CELL_SIZE);
                    }
                }
            }

            ctx.strokeStyle = 'rgba(0, 255, 136, 0.1)';
            ctx.lineWidth = 0.5;
            for (let i = 0; i <= GRID_WIDTH; i++) {
                ctx.beginPath();
                ctx.moveTo(i * CELL_SIZE, 0);
                ctx.lineTo(i * CELL_SIZE, canvas.height);
                ctx.stroke();
            }
            for (let i = 0; i <= GRID_HEIGHT; i++) {
                ctx.beginPath();
                ctx.moveTo(0, i * CELL_SIZE);
                ctx.lineTo(canvas.width, i * CELL_SIZE);
                ctx.stroke();
            }
        }

        function step() {
            grid = computeNextGeneration();
            generation++;
            document.getElementById('generation').textContent = generation;
            draw();
        }

        function autoStep() {
            step();
            if (running) {
                animationId = setTimeout(autoStep, 100);
            }
        }

        function getGridCoords(e) {
            const rect = canvas.getBoundingClientRect();
            const x = e.clientX - rect.left;
            const y = e.clientY - rect.top;
            const gridX = Math.floor(x / CELL_SIZE);
            const gridY = Math.floor(y / CELL_SIZE);
            return { gridX, gridY };
        }

        let isDrawing = false;

        canvas.addEventListener('mousedown', (e) => {
            isDrawing = true;
            const { gridX, gridY } = getGridCoords(e);
            if (gridX >= 0 && gridX < GRID_WIDTH && gridY >= 0 && gridY < GRID_HEIGHT) {
                grid[gridY][gridX] = 1 - grid[gridY][gridX];
                draw();
            }
        });

        canvas.addEventListener('mousemove', (e) => {
            if (isDrawing) {
                const { gridX, gridY } = getGridCoords(e);
                if (gridX >= 0 && gridX < GRID_WIDTH && gridY >= 0 && gridY < GRID_HEIGHT) {
                    grid[gridY][gridX] = 1 - grid[gridY][gridX];
                    draw();
                }
            }
        });

        canvas.addEventListener('mouseup', () => {
            isDrawing = false;
        });

        canvas.addEventListener('mouseleave', () => {
            isDrawing = false;
        });

        canvas.addEventListener('dblclick', () => {
            grid = Array(GRID_HEIGHT).fill(null).map(() => Array(GRID_WIDTH).fill(0));
            generation = 0;
            running = false;
            if (animationId) clearTimeout(animationId);
            document.getElementById('play').textContent = 'Play';
            document.getElementById('generation').textContent = '0';
            draw();
        });

        document.getElementById('step').addEventListener('click', step);

        document.getElementById('play').addEventListener('click', function() {
            running = !running;
            if (running) {
                this.textContent = 'Pause';
                autoStep();
            } else {
                this.textContent = 'Play';
                if (animationId) clearTimeout(animationId);
            }
        });

        document.getElementById('random').addEventListener('click', function() {
            for (let y = 0; y < GRID_HEIGHT; y++) {
                for (let x = 0; x < GRID_WIDTH; x++) {
                    grid[y][x] = Math.random() < 0.3 ? 1 : 0;
                }
            }
            generation = 0;
            running = false;
            document.getElementById('play').textContent = 'Play';
            document.getElementById('generation').textContent = '0';
            draw();
        });

        document.getElementById('clear').addEventListener('click', function() {
            grid = Array(GRID_HEIGHT).fill(null).map(() => Array(GRID_WIDTH).fill(0));
            generation = 0;
            running = false;
            if (animationId) clearTimeout(animationId);
            document.getElementById('play').textContent = 'Play';
            document.getElementById('generation').textContent = '0';
            draw();
        });

        window.life = {
            w: GRID_WIDTH,
            h: GRID_HEIGHT,
            get(x, y) {
                if (x < 0 || x >= GRID_WIDTH || y < 0 || y >= GRID_HEIGHT) {
                    return 0;
                }
                return grid[y][x];
            },
            set(x, y, v) {
                if (x >= 0 && x < GRID_WIDTH && y >= 0 && y < GRID_HEIGHT) {
                    grid[y][x] = v ? 1 : 0;
                }
                draw();
            },
            step() {
                step();
            },
            clear() {
                grid = Array(GRID_HEIGHT).fill(null).map(() => Array(GRID_WIDTH).fill(0));
                generation = 0;
                running = false;
                if (animationId) clearTimeout(animationId);
                document.getElementById('play').textContent = 'Play';
                document.getElementById('generation').textContent = '0';
                draw();
            }
        };

        draw();
    </script>
</body>
</html>
